import { useEffect, useMemo, useRef, useState } from "react";
import { Link, Route, Switch, useLocation } from "wouter";
import { trpc } from "@/lib/trpc";
import { MapView } from "@/components/Map";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { ArrowRight, ChevronRight, CircleCheck, Compass, Facebook, FileCheck2, Globe2, HeartHandshake, Instagram, Landmark, Linkedin, MapPin, Menu, MessageCircleMore, Music2, PinIcon, Search, ShieldCheck, Sparkles, Umbrella, UsersRound, WalletCards, X, Youtube } from "lucide-react";

const HERO_IMAGE = "/manus-storage/jlt-editorial-reference-hero_30c23fe4.jpg";
const PLANNING_IMAGE = "/manus-storage/jlt-expert-planning_fb9b017f.jpg";
const DETAILS_IMAGE = "/manus-storage/jlt-travel-details_a893c607.jpg";
const PROTECTION_IMAGE = "/manus-storage/jlt-protection-trust_cfbaff5b.jpg";

type Agent = {
  slug: string;
  displayName: string;
  businessName: string | null;
  biography: string;
  profilePhotoUrl: string | null;
  listingTown: string;
  townLatitude: number | null;
  townLongitude: number | null;
  websiteUrl: string | null;
  instagramUrl: string | null;
  tiktokUrl: string | null;
  facebookUrl: string | null;
  linkedinUrl: string | null;
  youtubeUrl: string | null;
  pinterestUrl: string | null;
  tags: Array<{ id: number; label: string; category: "destination" | "travel_type" }>;
};

type Partner = {
  name: string;
  slug: string;
  category: string | null;
  summary: string | null;
  logoUrl: string | null;
  websiteUrl: string | null;
};

type HolidayShowcase = {
  slug: string;
  title: string;
  summary: string;
  destination: string;
  travelPeriodLabel: string | null;
  durationNights: number | null;
  price: { mode: "from"; amount: number; currency: string; perPerson: boolean } | null;
  heroImageUrl: string;
};

const NAV_ITEMS = [
  { label: "Find an agent", href: "/find-an-agent" },
  { label: "Why JLT", href: "/why-jlt" },
  { label: "Your protection", href: "/your-protection" },
  { label: "Partners", href: "/partners" },
];

function publicPrefix() {
  return typeof window !== "undefined" && window.location.pathname.startsWith("/consumer") ? "/consumer" : "";
}

function publicHref(path: string) {
  const prefix = publicPrefix();
  return `${prefix}${path === "/" ? "" : path}` || "/";
}

export default function ConsumerSite() {
  const prefix = publicPrefix();
  const [location] = useLocation();
  useEffect(() => {
    const publicPath = location.startsWith("/consumer") ? location.slice("/consumer".length) || "/" : location;
    const pageTitles: Record<string, string> = {
      "/": "The JLT Group | Travel, personally arranged",
      "/find-an-agent": "Find a JLT travel expert | The JLT Group",
      "/why-jlt": "Why book with JLT | The JLT Group",
      "/your-protection": "Your travel protection | The JLT Group",
      "/partners": "Travel partners | The JLT Group",
      "/privacy": "Privacy notice | The JLT Group",
      "/terms": "Website terms | The JLT Group",
    };
    document.title = publicPath.startsWith("/travel-agents/") ? "JLT travel expert | The JLT Group" : (pageTitles[publicPath] ?? "The JLT Group");
    const description = "Meet independent JLT travel experts and discover a more personal way to arrange your next trip.";
    let descriptionMeta = document.querySelector('meta[name="description"]') as HTMLMetaElement | null;
    if (!descriptionMeta) { descriptionMeta = document.createElement("meta"); descriptionMeta.name = "description"; document.head.appendChild(descriptionMeta); }
    descriptionMeta.content = description;
    let canonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
    if (!canonical) { canonical = document.createElement("link"); canonical.rel = "canonical"; document.head.appendChild(canonical); }
    canonical.href = `https://www.thejltgroup.co.uk${publicPath === "/" ? "" : publicPath}`;
    let robots = document.querySelector('meta[name="robots"]') as HTMLMetaElement | null;
    if (!robots) { robots = document.createElement("meta"); robots.name = "robots"; document.head.appendChild(robots); }
    robots.content = "index,follow";
  }, [location]);
  return <div className="min-h-screen bg-[#fcfcfa] text-[#13242f] font-sans">
    <ConsumerHeader />
    <main>
      <Switch>
        <Route path={`${prefix}/`} component={ConsumerHome} />
        <Route path={`${prefix}/find-an-agent`} component={FindAnAgent} />
        <Route path={`${prefix}/travel-agents/:agentSlug/holiday-showcases/:showcaseSlug`}>{({ agentSlug, showcaseSlug }) => <HolidayShowcaseDetail agentSlug={agentSlug} showcaseSlug={showcaseSlug} />}</Route>
        <Route path={`${prefix}/travel-agents/:slug`}>{({ slug }) => <AgentProfile slug={slug} />}</Route>
        <Route path={`${prefix}/why-jlt`} component={WhyJlt} />
        <Route path={`${prefix}/your-protection`} component={ProtectionPage} />
        <Route path={`${prefix}/partners`} component={PartnersPage} />
        <Route path={`${prefix}/privacy`} component={PrivacyPage} />
        <Route path={`${prefix}/terms`} component={PublicTermsPage} />
        <Route component={ConsumerNotFound} />
      </Switch>
    </main>
    <ConsumerFooter />
  </div>;
}

function ConsumerHeader() {
  const [open, setOpen] = useState(false);
  return <header className="sticky top-0 z-40 border-b border-slate-200/80 bg-[#fcfcfa]/95 backdrop-blur">
    <div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8">
      <Link href={publicHref("/")} className="group flex items-center gap-3 no-underline"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#102632] text-[#70ffe8] shadow-sm"><span className="text-base font-black tracking-tight">JLT</span></div><div><p className="font-semibold tracking-[-0.02em] text-[#102632] leading-none">The JLT Group</p><p className="mt-1 text-[10px] uppercase tracking-[0.18em] text-[#5f6e76]">Travel, personally arranged</p></div></Link>
      <nav className="hidden items-center gap-7 lg:flex">{NAV_ITEMS.map(item => <Link key={item.href} href={publicHref(item.href)} className="text-sm font-medium text-[#3c4e57] transition-colors hover:text-[#008e81]">{item.label}</Link>)}<Link href={publicHref("/find-an-agent")} className="rounded-full bg-[#102632] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-[#1e3a48]">Find your expert</Link></nav>
      <button onClick={() => setOpen(value => !value)} aria-expanded={open} aria-label="Toggle navigation" className="grid h-10 w-10 place-items-center rounded-full border border-slate-200 text-[#102632] lg:hidden">{open ? <X size={19} /> : <Menu size={20} />}</button>
    </div>
    {open && <nav className="border-t border-slate-200 bg-[#fcfcfa] px-5 py-4 lg:hidden"><div className="mx-auto grid max-w-7xl gap-1">{NAV_ITEMS.map(item => <Link onClick={() => setOpen(false)} key={item.href} href={publicHref(item.href)} className="rounded-lg px-3 py-3 text-sm font-medium text-[#334751] hover:bg-[#eafbf8]">{item.label}</Link>)}<Link onClick={() => setOpen(false)} href={publicHref("/find-an-agent")} className="mt-2 rounded-lg bg-[#102632] px-3 py-3 text-center text-sm font-medium text-white">Find your expert</Link></div></nav>}
  </header>;
}

function ConsumerHome() {
  const { data: agents = [] } = trpc.consumerSite.public.listAgents.useQuery();
  return <>
    <section className="relative isolate overflow-hidden bg-[#102632]"><img src={HERO_IMAGE} alt="A couple pausing to plan their Mediterranean journey" className="absolute inset-0 -z-20 h-full w-full object-cover opacity-70" /><div className="absolute inset-0 -z-10 bg-[linear-gradient(90deg,rgba(9,26,35,.97)_0%,rgba(9,26,35,.87)_46%,rgba(9,26,35,.18)_100%)]" /><div className="mx-auto grid min-h-[660px] max-w-7xl content-center px-5 py-20 lg:px-8 lg:py-24"><div className="max-w-3xl"><p className="inline-flex items-center gap-2 rounded-full border border-[#70ffe8]/30 bg-[#70ffe8]/10 px-3 py-1.5 text-xs font-semibold uppercase tracking-[.15em] text-[#a6fff0]"><Compass size={14} /> A more human way to book</p><h1 className="mt-7 font-serif text-5xl font-medium tracking-[-.055em] text-white sm:text-6xl lg:text-8xl">The internet can book a holiday.<br /><em className="text-[#70ffe8]">It cannot know you.</em></h1><p className="mt-7 max-w-xl text-lg leading-relaxed text-slate-200">A JLT travel expert turns a wish list, a few strong opinions and a lot of tabs into one trip that feels considered from the first conversation.</p><div className="mt-9 flex flex-col gap-3 sm:flex-row"><Link href={publicHref("/find-an-agent")} className="inline-flex items-center justify-center gap-2 rounded-full bg-[#70ffe8] px-6 py-3.5 font-semibold text-[#102632] transition hover:bg-white">Find your travel expert <ArrowRight size={17} /></Link><Link href={publicHref("/why-jlt")} className="inline-flex items-center justify-center gap-2 rounded-full border border-white/35 px-6 py-3.5 font-semibold text-white transition hover:bg-white/10">Why use an independent expert?</Link></div></div></div><div className="border-t border-white/10"><div className="mx-auto grid max-w-7xl grid-cols-1 divide-y divide-white/10 px-5 text-slate-100 sm:grid-cols-3 sm:divide-x sm:divide-y-0 lg:px-8"><TrustMetric icon={<MessageCircleMore />} heading="Someone who listens" body="Because a memorable holiday is personal before it is bookable." /><TrustMetric icon={<Compass />} heading="Someone who narrows the noise" body="Fewer tabs. Better questions. Choices that make sense together." /><TrustMetric icon={<HeartHandshake />} heading="Someone who stays involved" body="A named expert before, during and after the journey." /></div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><div className="grid items-center gap-10 lg:grid-cols-[.9fr_1.1fr]"><div className="relative"><img src={PLANNING_IMAGE} alt="Travel plans being considered together" className="aspect-[4/3] w-full rounded-[2.5rem] object-cover shadow-2xl shadow-[#102632]/15" /><div className="absolute -bottom-5 -right-2 max-w-[235px] rounded-2xl bg-[#70ffe8] p-5 text-[#102632] shadow-xl sm:right-7"><p className="font-serif text-3xl leading-none">10 tabs</p><p className="mt-2 text-sm font-medium leading-snug">are rarely ten better answers.</p></div></div><div className="lg:pl-12"><Eyebrow>Choice is not always freedom</Eyebrow><h2 className="mt-4 font-serif text-4xl tracking-[-.045em] sm:text-6xl">The important part is not finding more options.</h2><p className="mt-6 max-w-xl text-lg leading-relaxed text-[#51636d]">It is noticing the small things that change the whole trip: who really needs an early flight, whether a hotel is in the right place, or why an itinerary that looks impressive on a screen might be exhausting in real life.</p><Link href={publicHref("/why-jlt")} className="mt-8 inline-flex items-center gap-2 font-semibold text-[#007e72] hover:text-[#102632]">See what an expert adds <ArrowRight size={17} /></Link></div></div></section>
    <section className="overflow-hidden bg-[#f2eee7]"><div className="mx-auto grid max-w-7xl gap-12 px-5 py-20 lg:grid-cols-[1fr_.9fr] lg:px-8 lg:py-28"><div><Eyebrow>Not a booking. A better decision.</Eyebrow><h2 className="mt-4 max-w-3xl font-serif text-4xl tracking-[-.045em] sm:text-6xl">Travel is too personal to leave to a sorting filter.</h2><div className="mt-10 grid gap-4 sm:grid-cols-3"><ValueCard number="01" title="Start with your real brief" body="The people, pace, priorities and small non-negotiables that rarely fit in a search box." /><ValueCard number="02" title="Make the trade-offs clearer" body="An expert helps you spend attention where it actually changes the experience." /><ValueCard number="03" title="Have a person to call" body="When plans shift, you are not starting again with a stranger and a reference number." /></div></div><div className="self-end rounded-[2.5rem] bg-[#102632] p-8 text-white sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#70ffe8]">The JLT difference</p><p className="mt-5 font-serif text-4xl leading-tight tracking-[-.04em]">“A holiday should feel like you chose it. Not like an algorithm eventually wore you down.”</p><p className="mt-6 text-sm leading-relaxed text-slate-300">That is why every JLT booking begins with a conversation, not a checkout button.</p></div></div></section>
    <section className="bg-[#e8f7f3]"><div className="mx-auto grid max-w-7xl items-stretch gap-8 px-5 py-20 lg:grid-cols-[.8fr_1.2fr] lg:px-8 lg:py-28"><div className="relative min-h-[440px] overflow-hidden rounded-[2.5rem]"><img src={PROTECTION_IMAGE} alt="A traveller keeping important travel documents close" className="absolute inset-0 h-full w-full object-cover" /><div className="absolute inset-x-5 bottom-5 rounded-2xl bg-[#102632]/95 p-5 text-white"><Landmark className="text-[#70ffe8]" size={24} /><p className="mt-3 font-serif text-2xl">Confidence is not an add-on.</p></div></div><div className="flex flex-col justify-center lg:pl-8"><Eyebrow>PTS protection, explained clearly</Eyebrow><h2 className="mt-4 font-serif text-4xl tracking-[-.045em] sm:text-6xl">Your money should have a better journey too.</h2><p className="mt-6 max-w-2xl text-lg leading-relaxed text-[#51636d]">JLT works through the PTS protection framework. The details of protection depend on the arrangements you book, but your expert will explain what applies before you commit—not after you need it.</p><div className="mt-8 grid gap-3 sm:grid-cols-2"><CheckLine text="PTS Trust Account protection" /><CheckLine text="ATOL context where flights are included" /><CheckLine text="Booking-specific documents" /><CheckLine text="A named expert to explain them" /></div><Link href={publicHref("/your-protection")} className="mt-9 inline-flex w-fit items-center gap-2 rounded-full bg-[#102632] px-6 py-3.5 font-semibold text-white hover:bg-[#1e3a48]">Understand your protection <ArrowRight size={17} /></Link></div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><div className="rounded-[2.5rem] bg-[#102632] p-8 text-white sm:p-12 lg:grid lg:grid-cols-[1.1fr_.9fr] lg:items-center lg:gap-14 lg:p-16"><div><Eyebrow>Find your person</Eyebrow><h2 className="mt-4 font-serif text-4xl tracking-[-.045em] sm:text-6xl">A better trip starts with the right conversation.</h2><p className="mt-5 max-w-xl leading-relaxed text-slate-300">Search by destination, holiday style or location, then share your ideas privately with an approved JLT expert.</p><Link href={publicHref("/find-an-agent")} className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#70ffe8] px-6 py-3.5 font-semibold text-[#102632] transition hover:bg-white">Explore travel experts <ArrowRight size={17} /></Link></div><div className="mt-10 rounded-3xl bg-white/10 p-7 lg:mt-0"><p className="text-sm font-medium text-[#b8d8d4]">Currently discoverable</p><p className="mt-1 font-serif text-7xl tracking-[-.06em] text-[#70ffe8]">{agents.length}</p><p className="mt-2 text-sm leading-relaxed text-slate-300">approved JLT travel {agents.length === 1 ? "expert" : "experts"} ready for a better kind of travel conversation.</p><div className="mt-6 flex -space-x-2">{agents.slice(0, 4).map((agent) => agent.profilePhotoUrl ? <img key={agent.slug} src={agent.profilePhotoUrl} alt="" className="h-11 w-11 rounded-full border-2 border-[#102632] object-cover" /> : <span key={agent.slug} className="grid h-11 w-11 place-items-center rounded-full border-2 border-[#102632] bg-[#d4f8f0] text-xs font-semibold text-[#116e65]">{agent.displayName.split(" ").map(name => name[0]).join("").slice(0, 2)}</span>)}</div></div></div></section>
  </>;
}

function FindAnAgent() {
  const { data: tags = [] } = trpc.consumerSite.tags.list.useQuery();
  const [search, setSearch] = useState("");
  const [selectedTagIds, setSelectedTagIds] = useState<number[]>([]);
  const { data: agents = [], isLoading } = trpc.consumerSite.public.listAgents.useQuery({ search: search || undefined, tagIds: selectedTagIds });
  const destinationTags = tags.filter(tag => tag.category === "destination");
  const travelTypeTags = tags.filter(tag => tag.category === "travel_type");
  const toggle = (id: number) => setSelectedTagIds(current => current.includes(id) ? current.filter(value => value !== id) : [...current, id]);
  return <>
    <PageHero eyebrow="Find your travel expert" title="The person behind your next great trip." body="Choose by destination, holiday style or town. Every expert listed here has an approved JLT profile and is currently Active." />
    <section className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><div className="grid gap-8 lg:grid-cols-[310px_1fr]"><aside className="lg:sticky lg:top-24 lg:self-start" aria-label="Travel expert filters"><div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="relative"><Search className="absolute left-3 top-3 text-[#70818a]" size={18} aria-hidden="true" /><Input aria-label="Search travel experts by name, town or speciality" value={search} onChange={event => setSearch(event.target.value)} className="h-11 border-slate-200 pl-10" placeholder="Name, town or speciality" /></div><FilterGroup title="Destinations" tags={destinationTags} selected={selectedTagIds} onToggle={toggle} /><FilterGroup title="Travel types" tags={travelTypeTags} selected={selectedTagIds} onToggle={toggle} />{selectedTagIds.length > 0 && <button onClick={() => setSelectedTagIds([])} className="mt-5 text-sm font-medium text-[#007e72] underline underline-offset-4">Clear filters</button>}</div></aside><div><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-[#60717a]" aria-live="polite" role="status">{isLoading ? "Finding experts…" : `${agents.length} ${agents.length === 1 ? "expert" : "experts"} found`}</p><p className="inline-flex items-center gap-2 text-xs text-[#60717a]"><ShieldCheck size={14} className="text-[#008e81]" aria-hidden="true" /> Approved profiles only</p></div><AgentMap agents={agents} /><div className="mt-7 grid gap-5 md:grid-cols-2" aria-label="Travel expert results">{isLoading ? [1, 2, 3, 4].map(item => <div key={item} className="h-72 animate-pulse rounded-2xl bg-slate-100" />) : agents.map(agent => <AgentCard key={agent.slug} agent={agent} />)}</div>{!isLoading && agents.length === 0 && <EmptyAgentState hasFilters={Boolean(search || selectedTagIds.length)} />}</div></div></section>
  </>;
}

function AgentProfile({ slug }: { slug: string }) {
  const { data: agent, isLoading, error } = trpc.consumerSite.public.getAgent.useQuery({ slug });
  const { data: showcases = [] } = trpc.consumerSite.public.listShowcasesForAgent.useQuery({ agentSlug: slug });
  if (isLoading) return <section className="mx-auto max-w-6xl px-5 py-20 lg:px-8"><div className="h-96 animate-pulse rounded-3xl bg-slate-100" /></section>;
  if (error || !agent) return <ConsumerNotFound />;
  return <>
    <section className="bg-[#eafbf8]"><div className="mx-auto max-w-6xl px-5 py-10 lg:px-8"><Link href={publicHref("/find-an-agent")} className="inline-flex items-center gap-1 text-sm font-medium text-[#047d71] hover:underline">← All travel experts</Link><div className="mt-10 grid gap-8 lg:grid-cols-[270px_1fr]"><div className="aspect-square max-w-[270px] overflow-hidden rounded-[2rem] bg-[#d1f4ed]">{agent.profilePhotoUrl ? <img src={agent.profilePhotoUrl} alt={agent.displayName} className="h-full w-full object-cover" /> : <div className="grid h-full place-items-center text-6xl font-serif text-[#177c71]">{agent.displayName.charAt(0)}</div>}</div><div className="self-center"><p className="inline-flex items-center gap-1.5 text-sm font-medium text-[#047d71]"><MapPin size={16} /> {agent.listingTown}</p><h1 className="mt-3 font-serif text-5xl tracking-[-.045em] sm:text-6xl">{agent.displayName}</h1>{agent.businessName && <p className="mt-2 text-lg text-[#53656e]">{agent.businessName}</p>}<div className="mt-6 flex flex-wrap gap-2">{agent.tags.map(tag => <span key={tag.id} className="rounded-full bg-white px-3 py-1.5 text-sm font-medium text-[#2f5452] shadow-sm">{tag.label}</span>)}</div></div></div></div></section>
    <section className="mx-auto grid max-w-6xl gap-12 px-5 py-16 lg:grid-cols-[1fr_380px] lg:px-8 lg:py-20"><article><Eyebrow>Meet your travel expert</Eyebrow><p className="mt-5 whitespace-pre-wrap text-lg leading-8 text-[#41565f]">{agent.biography}</p>{showcases.length > 0 && <div className="mt-12 border-t border-slate-200 pt-9"><div className="flex flex-wrap items-end justify-between gap-3"><div><Eyebrow>Travel inspiration</Eyebrow><h2 className="mt-2 font-serif text-3xl tracking-[-.04em]">Ideas {agent.displayName.split(" ")[0]} has put together.</h2></div><p className="max-w-sm text-sm leading-6 text-[#61727a]">Itineraries to inspire a conversation, not a live quote.</p></div><div className="mt-6 grid gap-5 sm:grid-cols-2">{showcases.map((showcase) => <HolidayShowcaseCard key={showcase.slug} agentSlug={slug} showcase={showcase} />)}</div></div>}<div className="mt-12 border-t border-slate-200 pt-8"><h2 className="font-serif text-3xl tracking-[-.04em]">Let’s start planning</h2><p className="mt-3 max-w-2xl leading-relaxed text-[#61727a]">Share some initial ideas and {agent.displayName.split(" ")[0]} will reply directly. Their contact details are kept private; your enquiry is sent securely.</p><EnquiryForm agent={agent} /></div></article><aside className="space-y-5"><div className="rounded-3xl bg-[#102632] p-6 text-white"><p className="text-sm text-slate-300">Why book with a JLT expert?</p><ul className="mt-5 space-y-4 text-sm leading-relaxed text-slate-100"><li className="flex gap-2"><CheckCircle /> Independent advice shaped around you</li><li className="flex gap-2"><CheckCircle /> One expert who understands the details</li><li className="flex gap-2"><CheckCircle /> Protection information made clear</li></ul><Link href={publicHref("/why-jlt")} className="mt-6 inline-flex text-sm font-semibold text-[#70ffe8] hover:text-white">Why JLT <ArrowRight size={15} className="ml-1" /></Link></div><SocialLinks agent={agent} /></aside></section>
  </>;
}

function HolidayShowcaseCard({ agentSlug, showcase }: { agentSlug: string; showcase: HolidayShowcase }) {
  return <Link href={publicHref(`/travel-agents/${agentSlug}/holiday-showcases/${showcase.slug}`)} className="group overflow-hidden rounded-3xl border border-slate-200 bg-white no-underline shadow-sm transition hover:-translate-y-1 hover:shadow-xl hover:shadow-[#102632]/10"><div className="relative aspect-[4/3] overflow-hidden bg-[#eafbf8]"><img src={showcase.heroImageUrl} alt="" className="h-full w-full object-cover transition duration-500 group-hover:scale-105" onError={(event) => { event.currentTarget.style.display = "none"; }} /><div className="absolute inset-x-4 bottom-4 flex items-center justify-between gap-2"><span className="rounded-full bg-[#102632]/90 px-3 py-1.5 text-xs font-semibold text-white backdrop-blur">{showcase.destination}</span>{showcase.price && <span className="rounded-full bg-[#70ffe8] px-3 py-1.5 text-xs font-semibold text-[#102632]">From {new Intl.NumberFormat("en-GB", { style: "currency", currency: showcase.price.currency, maximumFractionDigits: 0 }).format(showcase.price.amount)} pp</span>}</div></div><div className="p-5"><p className="text-xs font-medium text-[#008e81]">{showcase.durationNights ? `${showcase.durationNights} nights` : "Travel inspiration"}{showcase.travelPeriodLabel ? ` · ${showcase.travelPeriodLabel}` : ""}</p><h3 className="mt-2 font-serif text-2xl leading-tight tracking-[-.03em] text-[#102632] group-hover:text-[#007e72]">{showcase.title}</h3><p className="mt-3 line-clamp-3 text-sm leading-6 text-[#60717a]">{showcase.summary}</p><span className="mt-5 inline-flex items-center gap-1.5 text-sm font-semibold text-[#007e72]">Explore this idea <ArrowRight size={15} /></span></div></Link>;
}

function HolidayShowcaseDetail({ agentSlug, showcaseSlug }: { agentSlug: string; showcaseSlug: string }) {
  const { data, isLoading, error } = trpc.consumerSite.public.getShowcase.useQuery({ agentSlug, showcaseSlug });
  if (isLoading) return <section className="mx-auto max-w-6xl px-5 py-20 lg:px-8"><div className="h-[520px] animate-pulse rounded-3xl bg-slate-100" /></section>;
  if (error || !data) return <ConsumerNotFound />;
  const { agent, showcase } = data;
  return <><section className="relative isolate overflow-hidden bg-[#102632]"><img src={showcase.heroImageUrl} alt="" className="absolute inset-0 -z-20 h-full w-full object-cover opacity-55" onError={(event) => { event.currentTarget.style.display = "none"; }} /><div className="absolute inset-0 -z-10 bg-[#102632]/80" /><div className="mx-auto max-w-6xl px-5 py-12 text-white lg:px-8 lg:py-20"><Link href={publicHref(`/travel-agents/${agentSlug}`)} className="inline-flex items-center gap-1 text-sm font-medium text-[#a6fff0] hover:underline">← Back to {agent.displayName}</Link><p className="mt-12 text-xs font-semibold uppercase tracking-[.16em] text-[#70ffe8]">{showcase.destination}</p><h1 className="mt-4 max-w-4xl font-serif text-5xl tracking-[-.055em] sm:text-7xl">{showcase.title}</h1><p className="mt-6 max-w-2xl text-lg leading-8 text-slate-200">{showcase.summary}</p><div className="mt-8 flex flex-wrap gap-2 text-sm">{showcase.durationNights && <span className="rounded-full border border-white/25 px-3 py-1.5">{showcase.durationNights} nights</span>}{showcase.travelPeriodLabel && <span className="rounded-full border border-white/25 px-3 py-1.5">{showcase.travelPeriodLabel}</span>}{showcase.price && <span className="rounded-full bg-[#70ffe8] px-3 py-1.5 font-semibold text-[#102632]">From {new Intl.NumberFormat("en-GB", { style: "currency", currency: showcase.price.currency, maximumFractionDigits: 0 }).format(showcase.price.amount)} per person</span>}</div></div></section><section className="mx-auto grid max-w-6xl gap-12 px-5 py-16 lg:grid-cols-[1fr_360px] lg:px-8 lg:py-20"><article>{showcase.itinerary.length > 0 && <section><Eyebrow>Suggested itinerary</Eyebrow><div className="mt-7 space-y-5">{showcase.itinerary.map((item: any, index: number) => <div key={`${item.day ?? index}-${item.title}`} className="grid gap-4 rounded-2xl border border-slate-200 bg-white p-5 sm:grid-cols-[72px_1fr]"><p className="font-serif text-2xl text-[#008e81]">{item.day ? `Day ${item.day}` : String(index + 1).padStart(2, "0")}</p><div><h2 className="font-serif text-2xl text-[#102632]">{item.title}</h2>{item.description && <p className="mt-2 leading-7 text-[#5e7079]">{item.description}</p>}{item.highlights?.length > 0 && <ul className="mt-3 flex flex-wrap gap-2">{item.highlights.map((highlight: string) => <li key={highlight} className="rounded-full bg-[#eafbf8] px-3 py-1.5 text-xs font-medium text-[#27746c]">{highlight}</li>)}</ul>}</div></div>)}</div></section>}{showcase.accommodationOptions.length > 0 && <section className="mt-12"><Eyebrow>Places to stay</Eyebrow><div className="mt-6 grid gap-4 sm:grid-cols-2">{showcase.accommodationOptions.map((option: any) => <div key={option.name} className="rounded-2xl bg-[#f2eee7] p-5"><h2 className="font-serif text-2xl text-[#102632]">{option.name}</h2><p className="mt-1 text-sm text-[#61727a]">{[option.location, option.room, option.board].filter(Boolean).join(" · ")}</p>{option.description && <p className="mt-3 text-sm leading-6 text-[#53666f]">{option.description}</p>}</div>)}</div></section>}{(showcase.inclusions.length > 0 || showcase.practicalNotes.length > 0) && <section className="mt-12 grid gap-5 sm:grid-cols-2"><div className="rounded-2xl bg-[#e8f7f3] p-6"><h2 className="font-serif text-2xl text-[#102632]">Included</h2><ul className="mt-4 space-y-2 text-sm leading-6 text-[#47636a]">{showcase.inclusions.map((item: string) => <li key={item} className="flex gap-2"><CheckCircle /> {item}</li>)}</ul></div><div className="rounded-2xl border border-slate-200 p-6"><h2 className="font-serif text-2xl text-[#102632]">Good to know</h2><ul className="mt-4 space-y-2 text-sm leading-6 text-[#586a72]">{showcase.practicalNotes.map((item: string) => <li key={item}>{item}</li>)}</ul></div></section>}</article><aside><div className="sticky top-24 rounded-3xl bg-[#102632] p-6 text-white"><p className="text-sm text-[#b8d8d4]">Like the shape of this trip?</p><h2 className="mt-3 font-serif text-3xl">Make it your own.</h2><p className="mt-3 text-sm leading-6 text-slate-300">This is travel inspiration, not a live quote. Send {agent.displayName.split(" ")[0]} a private enquiry to explore what would work for you.</p><EnquiryForm agent={agent} showcaseSlug={showcase.slug} /></div></aside></section></>;
}

function AgentMap({ agents }: { agents: Agent[] }) {
  const mapRef = useRef<google.maps.Map | null>(null);
  const [ready, setReady] = useState(false);
  const [mapError, setMapError] = useState(false);
  const groupedTowns = useMemo(() => Object.values(agents.reduce<Record<string, Agent[]>>((acc, agent) => { const town = agent.listingTown.trim(); if (town) (acc[town] ??= []).push(agent); return acc; }, {})), [agents]);
  useEffect(() => {
    if (!ready || !mapRef.current || !window.google?.maps || groupedTowns.length === 0) return;
    let cancelled = false;
    const map = mapRef.current;
    const bounds = new window.google.maps.LatLngBounds();
    const geocoder = new window.google.maps.Geocoder();
    const markers: Array<{ setMap: (map: google.maps.Map | null) => void }> = [];
    groupedTowns.forEach((townAgents) => {
      const first = townAgents[0];
      const position = first.townLatitude !== null && first.townLongitude !== null ? { lat: first.townLatitude, lng: first.townLongitude } : null;
      const addMarker = (point: google.maps.LatLngLiteral) => {
        if (cancelled) return;
        const marker = new window.google.maps.Marker({ map, position: point, title: `${townAgents.length} JLT travel ${townAgents.length === 1 ? "expert" : "experts"} in ${first.listingTown}`, label: { text: String(townAgents.length), color: "#102632", fontWeight: "700" }, icon: { path: window.google.maps.SymbolPath.CIRCLE, fillColor: "#70ffe8", fillOpacity: 1, strokeColor: "#102632", strokeWeight: 2, scale: 15 } });
        markers.push(marker); bounds.extend(point);
      };
      if (position) addMarker(position); else geocoder.geocode({ address: `${first.listingTown}, United Kingdom` }, (results, status) => { if (status === "OK" && results?.[0]) addMarker(results[0].geometry.location.toJSON()); });
    });
    const timer = window.setTimeout(() => { if (!cancelled && !bounds.isEmpty()) map.fitBounds(bounds, 72); }, 800);
    return () => { cancelled = true; clearTimeout(timer); markers.forEach(marker => marker.setMap(null)); };
  }, [groupedTowns, ready]);
  if (!agents.length) return null;
  return <section aria-labelledby="agent-map-heading" className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between gap-4 border-b border-slate-100 px-5 py-4"><div><h2 id="agent-map-heading" className="font-semibold">Where our experts are based</h2><p className="mt-0.5 text-xs text-[#64747d]">Town-level markers only — never an agent’s precise address.</p></div><MapPin className="text-[#008e81]" size={20} aria-hidden="true" /></div><div className="relative h-[330px] bg-[#eafbf8]" aria-label="Map of JLT travel experts by town">{mapError ? <div className="grid h-full place-items-center px-6 text-center text-sm text-[#61727a]">The map is temporarily unavailable. You can still use the accessible expert list below.</div> : <MapView className="h-full w-full" initialCenter={{ lat: 54.5, lng: -3.2 }} initialZoom={5} onMapReady={map => { mapRef.current = map; setReady(true); }} />}</div><div className="flex flex-wrap gap-2 px-5 py-3" aria-label="Town summary">{groupedTowns.map(townAgents => <span key={townAgents[0].listingTown} className="rounded-full bg-[#eafbf8] px-3 py-1 text-xs font-medium text-[#27746c]">{townAgents[0].listingTown} · {townAgents.length}</span>)}</div></section>;
}

function EnquiryForm({ agent, showcaseSlug }: { agent: Agent; showcaseSlug?: string }) {
  const [form, setForm] = useState({ name: "", email: "", phone: "", brief: "" });
  const [consent, setConsent] = useState(false);
  const submit = trpc.consumerSite.public.submitEnquiry.useMutation({ onSuccess: () => { toast.success("Thank you — your enquiry has been passed to your JLT travel expert."); setForm({ name: "", email: "", phone: "", brief: "" }); setConsent(false); }, onError: error => toast.error(error.message) });
  const onSubmit = (event: React.FormEvent) => { event.preventDefault(); if (!consent) return toast.error("Please confirm that you agree to us passing your enquiry to this travel expert."); submit.mutate({ slug: agent.slug, customerName: form.name, customerEmail: form.email, customerPhone: form.phone || null, travelBrief: form.brief, showcaseSlug, consentConfirmed: true }); };
  return <form onSubmit={onSubmit} className="mt-7 space-y-4 rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div className="grid gap-4 sm:grid-cols-2"><PublicField label="Your name"><Input required value={form.name} onChange={event => setForm(current => ({ ...current, name: event.target.value }))} /></PublicField><PublicField label="Email address"><Input required type="email" value={form.email} onChange={event => setForm(current => ({ ...current, email: event.target.value }))} /></PublicField></div><PublicField label="Phone number" optional><Input type="tel" value={form.phone} onChange={event => setForm(current => ({ ...current, phone: event.target.value }))} /></PublicField><PublicField label="Tell us about your trip"><Textarea required minLength={20} rows={6} value={form.brief} onChange={event => setForm(current => ({ ...current, brief: event.target.value }))} placeholder="Where would you like to go, who is travelling, and what kind of trip are you dreaming of?" /></PublicField><label className="flex items-start gap-3 cursor-pointer"><Checkbox checked={consent} onCheckedChange={value => setConsent(value === true)} className="mt-0.5" /><span className="text-xs leading-relaxed text-[#61727a]">I agree that The JLT Group may securely pass this enquiry and my contact details to {agent.displayName}. I have read the <Link href={publicHref("/privacy")} className="font-medium text-[#007e72] underline">privacy notice</Link>.</span></label><Button disabled={submit.isPending} type="submit" className="w-full rounded-full bg-[#102632] py-6 font-semibold hover:bg-[#1e3a48]">{submit.isPending ? "Sending…" : <>Send a private enquiry <ArrowRight className="ml-2" size={17} /></>}</Button></form>;
}

function WhyJlt() { return <><PageHero eyebrow="Why book through JLT" title="The clever bit is knowing what to ignore." body="Independent expertise is not about adding more choice. It is about making the right choices feel easier." /><section className="mx-auto grid max-w-7xl gap-10 px-5 py-20 lg:grid-cols-[1fr_.9fr] lg:px-8 lg:py-28"><div><Eyebrow>When travel is personal</Eyebrow><h2 className="mt-4 font-serif text-5xl tracking-[-.05em] sm:text-6xl">The details are where the holiday lives.</h2><p className="mt-6 max-w-xl text-lg leading-8 text-[#53666f]">A website can tell you that a hotel has a pool. It cannot know that your child will be asleep before dinner, that you hate changing rooms, or that the whole point of this trip is to stop making decisions for a week.</p><p className="mt-5 max-w-xl text-lg leading-8 text-[#53666f]">A JLT expert turns those truths into a better brief, then does the searching, comparing and second-guessing with you—not instead of you.</p></div><img src={DETAILS_IMAGE} alt="A considered collection of travel details on a table" className="w-full rounded-[2.5rem] object-cover shadow-xl shadow-[#102632]/10" /></section><section className="bg-[#102632]"><div className="mx-auto grid max-w-7xl gap-px px-5 py-8 md:grid-cols-3 lg:px-8"><FeaturePoint icon={<Compass />} title="Less noise" body="You do not need a hundred hotels. You need the two or three that deserve your attention." /><FeaturePoint icon={<HeartHandshake />} title="More advocacy" body="Your expert represents your brief, not an impersonal search result." /><FeaturePoint icon={<MessageCircleMore />} title="Continuity" body="The person who understands the trip is still there when a question appears later." /></div></section><section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><div className="rounded-[2.5rem] bg-[#f2eee7] p-8 sm:p-12"><Eyebrow>Independent, by design</Eyebrow><h2 className="mt-4 max-w-3xl font-serif text-4xl tracking-[-.04em] sm:text-5xl">The holiday is not a product. It is a promise you have made to yourself.</h2><p className="mt-6 max-w-2xl text-lg leading-8 text-[#53666f]">That is why an independent travel expert begins with the person travelling, not the thing that happens to be easiest to sell. Availability, terms and protection arrangements will always be explained in the context of your booking before you decide.</p><Link href={publicHref("/find-an-agent")} className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#102632] px-6 py-3.5 font-semibold text-white">Find your independent expert <ArrowRight size={17} /></Link></div></section></> }

function ProtectionPage() { return <><PageHero eyebrow="Your protection" title="The most relaxing part of a holiday should not be a leap of faith." body="Our role is to make protection easier to understand, before you commit—not to hide the important bits in a footer." /><section className="mx-auto grid max-w-7xl items-center gap-10 px-5 py-20 lg:grid-cols-[.85fr_1.15fr] lg:px-8 lg:py-28"><div className="relative overflow-hidden rounded-[2.5rem]"><img src={PROTECTION_IMAGE} alt="Travel documents being kept safely close" className="aspect-[4/5] w-full object-cover" /><div className="absolute inset-x-5 bottom-5 rounded-2xl bg-[#102632]/95 p-5 text-white"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#70ffe8]">Travel with trust</p><p className="mt-2 font-serif text-2xl">Clearer before you book. Calmer when you travel.</p></div></div><div><Eyebrow>How PTS fits in</Eyebrow><h2 className="mt-4 font-serif text-5xl tracking-[-.05em] sm:text-6xl">Protection deserves a plain-English explanation.</h2><p className="mt-6 max-w-2xl text-lg leading-8 text-[#53666f]">JLT works through the Protected Trust Services (PTS) framework. PTS describes Trust Account Protection as a way of keeping customer money connected to the arrangements it is there to pay for, with independent trustees forming part of the framework.</p><p className="mt-5 max-w-2xl text-base leading-7 text-[#64747d]">The exact protection applying to a holiday depends on how it is arranged. Your JLT expert will explain the relevant protection and provide booking-specific documentation before you make a payment.</p><a href="https://www.protectedtrustservices.com/for-travellers/" target="_blank" rel="noreferrer" className="mt-7 inline-flex items-center gap-2 font-semibold text-[#007e72] hover:text-[#102632]">Read PTS consumer information <ArrowRight size={17} /></a></div></section><section className="bg-[#e8f7f3]"><div className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><Eyebrow>Four pieces of the picture</Eyebrow><h2 className="mt-4 max-w-3xl font-serif text-4xl tracking-[-.04em] sm:text-5xl">The right protection depends on the way you book.</h2><div className="mt-10 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><ProtectionTile icon={<Landmark />} title="PTS Trust Account" body="The PTS framework includes Trust Account Protection and independent trustee oversight." /><ProtectionTile icon={<FileCheck2 />} title="Package Travel Regulations" body="These can apply to qualifying packages and linked travel arrangements, depending on the booking." /><ProtectionTile icon={<ShieldCheck />} title="ATOL, where applicable" body="For flight-inclusive packages, ATOL protection may apply as explained in your documents." /><ProtectionTile icon={<Umbrella />} title="Travel insurance" body="Separate travel insurance remains important for matters such as medical costs and personal belongings." /></div></div></section><section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><div className="grid gap-8 lg:grid-cols-[.7fr_1fr]"><h2 className="font-serif text-4xl tracking-[-.04em] sm:text-5xl">Before you pay, you should know four things.</h2><div className="grid gap-3 sm:grid-cols-2"><CheckLine text="Who is arranging the travel" /><CheckLine text="What protection applies" /><CheckLine text="Where this is confirmed" /><CheckLine text="Who to ask if anything is unclear" /></div></div><p className="mt-10 max-w-4xl border-t border-slate-200 pt-6 text-sm leading-7 text-[#64747d]">This page is a general introduction, not a substitute for the protection information and booking documents for your particular arrangements. Financial protection, Package Travel Regulations and ATOL applicability depend on booking circumstances. Please read the documents supplied for your holiday and ask your JLT expert for an explanation before you commit.</p></section></> }

function PartnersPage() { const { data: partners = [], isLoading } = trpc.consumerSite.public.listPartners.useQuery(); return <><PageHero eyebrow="Partners" title="Good travel starts with good company." body="A deliberately curated collection of travel partners, selected to give our experts more ways to create the right trip." /><section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28">{isLoading ? <div className="grid gap-5 md:grid-cols-3">{[1, 2, 3].map(item => <div key={item} className="h-56 animate-pulse rounded-3xl bg-slate-100" />)}</div> : partners.length ? <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{partners.map((partner: Partner) => <article key={partner.slug} className="group flex min-h-72 flex-col rounded-3xl border border-slate-200 bg-white p-7 shadow-sm transition hover:-translate-y-1 hover:shadow-xl hover:shadow-[#102632]/10"><div className="flex h-20 items-center"><div className="grid h-16 w-28 place-items-center overflow-hidden rounded-xl bg-[#f2eee7] p-3">{partner.logoUrl ? <img src={partner.logoUrl} alt={`${partner.name} logo`} className="max-h-full max-w-full object-contain" /> : <span className="font-serif text-xl text-[#102632]">{partner.name.slice(0, 2).toUpperCase()}</span>}</div></div>{partner.category && <p className="mt-5 text-xs font-semibold uppercase tracking-[.16em] text-[#008e81]">{partner.category}</p>}<h2 className="mt-2 font-serif text-3xl tracking-[-.03em]">{partner.name}</h2>{partner.summary && <p className="mt-4 text-sm leading-6 text-[#60717a]">{partner.summary}</p>}{partner.websiteUrl && <a href={partner.websiteUrl} target="_blank" rel="noreferrer" className="mt-auto inline-flex items-center gap-1.5 pt-6 text-sm font-semibold text-[#007e72] hover:text-[#102632]">Visit partner <ArrowRight size={15} /></a>}</article>)}</div> : <div className="rounded-[2.5rem] bg-[#f2eee7] px-8 py-16 text-center sm:px-16"><Sparkles className="mx-auto text-[#008e81]" size={30} /><h2 className="mt-5 font-serif text-4xl tracking-[-.04em]">A considered collection is on its way.</h2><p className="mx-auto mt-4 max-w-xl leading-relaxed text-[#5d7078]">We are taking care to curate this space. In the meantime, your JLT expert can talk you through the travel partners best suited to your plans.</p><Link href={publicHref("/find-an-agent")} className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#102632] px-5 py-3 font-semibold text-white">Find your expert <ArrowRight size={16} /></Link></div>}</section></> }

function PrivacyPage() { return <LegalPage title="Privacy notice" updated="September 2026"><p>When you submit an enquiry through an individual JLT travel expert’s public profile, we collect the information you enter in the form so that it can be passed securely to that selected expert and they can respond to your enquiry.</p><p>We do not display the expert’s private delivery email address on the public website. We retain a limited internal delivery record to help us maintain the reliability and security of the enquiry service.</p><p>We use appropriate technical and organisational measures to protect personal data. If you have a query about your data or this notice, please contact The JLT Group through the appropriate published business contact channel.</p></LegalPage> }
function PublicTermsPage() { return <LegalPage title="Website terms" updated="September 2026"><p>This website provides general information about The JLT Group and its independent travel experts. Content is intended as an introduction only and does not constitute an offer, quotation or confirmation of travel arrangements.</p><p>Any travel booking, payment, cancellation, amendment, supplier term or protection arrangement is governed by the specific documents provided in connection with that booking.</p></LegalPage> }

function ConsumerNotFound() { return <section className="mx-auto grid min-h-[55vh] max-w-4xl place-items-center px-5 py-20 text-center"><div><p className="text-sm font-semibold uppercase tracking-[.18em] text-[#008e81]">Page not found</p><h1 className="mt-4 font-serif text-5xl tracking-[-.05em]">Let’s find a better route.</h1><p className="mt-4 text-[#5e7079]">This page may have moved, or the travel expert you are looking for is not currently available.</p><Link href={publicHref("/find-an-agent")} className="mt-8 inline-flex rounded-full bg-[#102632] px-5 py-3 font-semibold text-white">Find a travel expert</Link></div></section> }

function ConsumerFooter() { return <footer className="bg-[#102632] text-white"><div className="mx-auto grid max-w-7xl gap-10 px-5 py-14 md:grid-cols-[1.1fr_.9fr_.9fr] lg:px-8"><div><p className="font-semibold text-lg">The JLT Group</p><p className="mt-3 max-w-sm text-sm leading-relaxed text-slate-300">Travel, personally arranged. Find an independent travel expert who can help make your next trip feel more like yours.</p></div><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#70ffe8]">Explore</p><div className="mt-4 grid gap-2">{NAV_ITEMS.map(item => <Link key={item.href} href={publicHref(item.href)} className="text-sm text-slate-300 hover:text-white">{item.label}</Link>)}</div></div><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#70ffe8]">Information</p><div className="mt-4 grid gap-2"><Link href={publicHref("/your-protection")} className="text-sm text-slate-300 hover:text-white">Your protection</Link><Link href={publicHref("/privacy")} className="text-sm text-slate-300 hover:text-white">Privacy notice</Link><Link href={publicHref("/terms")} className="text-sm text-slate-300 hover:text-white">Website terms</Link></div></div></div><div className="border-t border-white/10 px-5 py-5 text-center text-xs text-slate-400">© {new Date().getFullYear()} The JLT Group. All rights reserved.</div></footer> }

function AgentCard({ agent }: { agent: Agent }) { return <Link href={publicHref(`/travel-agents/${agent.slug}`)} className="group block overflow-hidden rounded-2xl border border-slate-200 bg-white no-underline shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex gap-4 p-5"><div className="grid h-16 w-16 shrink-0 place-items-center overflow-hidden rounded-2xl bg-[#d6f7f1] font-serif text-2xl text-[#177c71]">{agent.profilePhotoUrl ? <img src={agent.profilePhotoUrl} alt={agent.displayName} className="h-full w-full object-cover" /> : agent.displayName.charAt(0)}</div><div className="min-w-0"><p className="font-semibold text-[#102632] group-hover:text-[#007e72]">{agent.displayName}</p>{agent.businessName && <p className="mt-0.5 truncate text-sm text-[#667781]">{agent.businessName}</p>}<p className="mt-2 flex items-center gap-1.5 text-xs font-medium text-[#54706f]"><MapPin size={13} /> {agent.listingTown}</p></div></div><div className="border-t border-slate-100 px-5 py-4"><div className="flex flex-wrap gap-1.5">{agent.tags.slice(0, 3).map(tag => <span key={tag.id} className="rounded-full bg-[#eafbf8] px-2.5 py-1 text-xs font-medium text-[#24756c]">{tag.label}</span>)}</div><p className="mt-4 flex items-center gap-1.5 text-sm font-semibold text-[#007e72]">View profile <ArrowRight size={15} /></p></div></Link> }
function SocialLinks({ agent }: { agent: Agent }) { const links = [{ key: "websiteUrl", label: "Website", icon: <Globe2 size={18} /> }, { key: "instagramUrl", label: "Instagram", icon: <Instagram size={18} /> }, { key: "tiktokUrl", label: "TikTok", icon: <Music2 size={18} /> }, { key: "facebookUrl", label: "Facebook", icon: <Facebook size={18} /> }, { key: "linkedinUrl", label: "LinkedIn", icon: <Linkedin size={18} /> }, { key: "youtubeUrl", label: "YouTube", icon: <Youtube size={18} /> }, { key: "pinterestUrl", label: "Pinterest", icon: <PinIcon size={18} /> }] as const; const visible = links.filter(link => agent[link.key]); if (!visible.length) return null; return <div className="rounded-3xl border border-slate-200 bg-white p-5"><p className="text-sm font-medium text-[#52646d]">Find {agent.displayName.split(" ")[0]} online</p><div className="mt-4 flex flex-wrap gap-2">{visible.map(link => <a key={link.key} href={agent[link.key] ?? undefined} target="_blank" rel="noreferrer" aria-label={`${agent.displayName} on ${link.label}`} className="grid h-10 w-10 place-items-center rounded-full border border-slate-200 text-[#285b61] transition hover:border-[#008e81] hover:bg-[#eafbf8] hover:text-[#007e72]">{link.icon}</a>)}</div></div> }
function TrustMetric({ icon, heading, body }: { icon: React.ReactElement; heading: string; body: string }) { return <div className="flex gap-3 py-5 sm:px-6 first:pl-0"><div className="mt-0.5 text-[#70ffe8]">{icon}</div><div><p className="font-semibold">{heading}</p><p className="mt-1 text-sm leading-relaxed text-slate-300">{body}</p></div></div> }
function ValueCard({ number, title, body }: { number: string; title: string; body: string }) { return <div className="rounded-2xl border border-slate-200 bg-white p-6"><p className="text-sm font-semibold text-[#008e81]">{number}</p><h3 className="mt-8 font-serif text-2xl tracking-[-.03em]">{title}</h3><p className="mt-3 text-sm leading-relaxed text-[#60717a]">{body}</p></div> }
function CheckLine({ text }: { text: string }) { return <p className="flex items-center gap-3 text-sm font-medium text-[#314950]"><span className="grid h-6 w-6 place-items-center rounded-full bg-[#70ffe8] text-[#102632]"><ShieldCheck size={14} /></span>{text}</p> }
function CheckCircle() { return <span className="mt-0.5 grid h-4 w-4 shrink-0 place-items-center rounded-full bg-[#70ffe8] text-[#102632] text-[10px] font-bold">✓</span> }
function Eyebrow({ children }: { children: React.ReactNode }) { return <p className="text-xs font-semibold uppercase tracking-[.18em] text-[#008e81]">{children}</p> }
function PageHero({ eyebrow, title, body }: { eyebrow: string; title: string; body: string }) { return <section className="bg-[#102632] py-20 text-white sm:py-24"><div className="mx-auto max-w-4xl px-5 text-center lg:px-8"><Eyebrow>{eyebrow}</Eyebrow><h1 className="mt-5 font-serif text-5xl tracking-[-.05em] sm:text-6xl">{title}</h1><p className="mx-auto mt-6 max-w-2xl text-lg leading-relaxed text-slate-300">{body}</p></div></section> }
function FilterGroup({ title, tags, selected, onToggle }: { title: string; tags: Array<{ id: number; label: string }>; selected: number[]; onToggle: (id: number) => void }) { if (!tags.length) return null; return <div className="mt-6"><p className="text-xs font-semibold uppercase tracking-[.14em] text-[#70818a]">{title}</p><div className="mt-3 flex flex-wrap gap-2">{tags.map(tag => <button key={tag.id} onClick={() => onToggle(tag.id)} className={`rounded-full border px-3 py-1.5 text-xs font-medium transition ${selected.includes(tag.id) ? "border-[#008e81] bg-[#dffaf5] text-[#006f64]" : "border-slate-200 text-[#53656e] hover:border-[#a7cfc9]"}`}>{tag.label}</button>)}</div></div> }
function EmptyAgentState({ hasFilters }: { hasFilters: boolean }) { return <div className="rounded-2xl border border-dashed border-slate-300 bg-white px-6 py-14 text-center"><UsersRound className="mx-auto text-[#78a9a2]" size={30} /><h2 className="mt-4 font-serif text-3xl">{hasFilters ? "No matching experts just yet" : "Our directory is just getting started"}</h2><p className="mx-auto mt-3 max-w-lg text-sm leading-relaxed text-[#60717a]">{hasFilters ? "Try removing a filter or searching for a different destination or travel style." : "As JLT experts complete and receive approval for their public profiles, they will appear here."}</p></div> }
function PublicField({ label, optional, children }: { label: string; optional?: boolean; children: React.ReactNode }) { return <label className="grid gap-1.5 text-sm font-medium text-[#364d56]"><span>{label}{optional && <span className="ml-1 text-xs font-normal text-[#778991]">(optional)</span>}</span>{children}</label> }
function ContentSection({ title, children }: { title: string; children: React.ReactNode }) { return <section className="mx-auto grid max-w-7xl gap-8 px-5 py-20 lg:grid-cols-[.7fr_1fr] lg:px-8 lg:py-28"><h2 className="font-serif text-4xl tracking-[-.04em] sm:text-5xl">{title}</h2><div className="space-y-5 text-lg leading-8 text-[#53666f]">{children}</div></section> }
function FeatureBand() { return <section className="bg-[#102632]"><div className="mx-auto grid max-w-7xl gap-px px-5 py-5 md:grid-cols-3 lg:px-8">{[["Independent", "A travel expert who takes a broad view of what will work for you."], ["Personal", "A relationship that can begin long before your holiday is confirmed."], ["Considered", "Details, choices and documentation discussed with care."]].map(([title, body]) => <div key={title} className="p-7 text-white"><p className="font-serif text-3xl">{title}</p><p className="mt-3 text-sm leading-relaxed text-slate-300">{body}</p></div>)}</div></section> }
function ProtectionCard({ title, body }: { title: string; body: string }) { return <div className="rounded-2xl bg-white p-6"><Landmark className="text-[#008e81]" size={22} /><h3 className="mt-5 font-serif text-2xl">{title}</h3><p className="mt-3 text-sm leading-relaxed text-[#60717a]">{body}</p></div> }
function LegalPage({ title, updated, children }: { title: string; updated: string; children: React.ReactNode }) { return <section className="mx-auto max-w-3xl px-5 py-16 lg:px-8 lg:py-24"><Eyebrow>Legal information</Eyebrow><h1 className="mt-4 font-serif text-5xl tracking-[-.04em]">{title}</h1><p className="mt-3 text-sm text-[#6b7d85]">Last updated: {updated}</p><div className="mt-10 space-y-5 text-base leading-8 text-[#4f626b]">{children}</div></section> }
function FeaturePoint({ icon, title, body }: { icon: React.ReactNode; title: string; body: string }) { return <div className="border-b border-white/10 p-7 text-white md:border-b-0 md:border-r last:border-0"><div className="text-[#70ffe8]">{icon}</div><h3 className="mt-6 font-serif text-3xl tracking-[-.03em]">{title}</h3><p className="mt-3 text-sm leading-relaxed text-slate-300">{body}</p></div> }
function ProtectionTile({ icon, title, body }: { icon: React.ReactNode; title: string; body: string }) { return <article className="min-h-56 rounded-3xl bg-white p-6 shadow-sm"><div className="grid h-10 w-10 place-items-center rounded-full bg-[#d8f8f1] text-[#0b685e]">{icon}</div><h3 className="mt-7 font-serif text-2xl tracking-[-.03em]">{title}</h3><p className="mt-3 text-sm leading-relaxed text-[#60717a]">{body}</p></article> }
